const crypto = require('crypto');

const item = $input.item;
const headers = item.json.headers || {};
const hmacHeader = headers['content-hmac'] || headers['Content-Hmac'] || '';

// NOTA: dependendo da versao do n8n, o corpo cru (com a opcao "Raw Body"
// habilitada no node Webhook) pode aparecer em propriedades diferentes.
// Esta cadeia de fallback cobre os casos mais comuns; se a validacao HMAC
// falhar sempre, confira em n8n > Executions qual propriedade realmente
// contem o body cru e ajuste aqui.
const rawBody = item.json.rawBody
  || item.json.body
  || (item.binary && item.binary.data && Buffer.from(item.binary.data.data, 'base64').toString('utf8'))
  || JSON.stringify(item.json.body || item.json);

const secret = $env.CLICKSIGN_WEBHOOK_SECRET || '';
if (!secret) {
  throw new Error('CLICKSIGN_WEBHOOK_SECRET nao configurado no .env.');
}

const hash = crypto.createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');
const assinaturaEsperada = `sha256=${hash}`;

if (hmacHeader !== assinaturaEsperada) {
  throw new Error(`Assinatura HMAC invalida. Recebido: ${hmacHeader} | Esperado: ${assinaturaEsperada}`);
}

let body;
try {
  body = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
} catch (e) {
  body = item.json.body || item.json;
}

// Melhor tentativa de leitura do payload da Clicksign v3. O schema exato do
// evento de webhook nao foi confirmado com 100% de certeza na pesquisa —
// confira o payload real recebido (n8n > Executions) e ajuste os caminhos
// abaixo se os campos vierem vazios.
const eventoNome = body?.event?.name || body?.data?.attributes?.event_name || body?.name || 'desconhecido';
const envelopeId = body?.data?.attributes?.envelope?.id || body?.event?.data?.envelope?.id || body?.envelope?.id || body?.data?.relationships?.envelope?.data?.id || null;
const signerEmail = body?.data?.attributes?.signer?.email || body?.event?.data?.signer?.email || body?.signer?.email || null;
const assinadoEm = body?.data?.attributes?.signer?.signed_at || body?.event?.occurred_at || new Date().toISOString();

const nomeLower = String(eventoNome).toLowerCase();
let evento_tipo = 'outro';
if (nomeLower.includes('refus')) {
  evento_tipo = 'recusado';
} else if (nomeLower.includes('sign') || nomeLower.includes('close')) {
  evento_tipo = 'assinado';
}

function escapeSql(value) {
  return String(value ?? '').replace(/'/g, "''");
}

return {
  json: {
    evento_nome: eventoNome,
    evento_tipo,
    envelope_id: envelopeId,
    envelope_id_sql: escapeSql(envelopeId),
    signer_email: signerEmail,
    signer_email_sql: escapeSql(signerEmail),
    assinado_em: assinadoEm,
    payload_bruto: body
  }
};
